import{c as u,d as e,E as l,k as s,u as i,I as c,V as n,e as d,F as m,r as g,A as B,W as v,w as q,C as x,G as R,b as f,n as G,t as p}from"./index-rAvm-xWZ.js";const j=(r,b)=>{const a=r.__vccOpts||r;for(const[o,t]of b)a[o]=t;return a},z={class:"page narrow rules"},y={class:"stack"},C={class:"panel"},T={class:"panel"},L={class:"actions",style:{"margin-top":"16px"}},S={class:"hd"},E={class:"ic"},N={class:"nm"},h={class:"tg"},k={class:"ds"},A={class:"panel"},w={class:"wtable"},D={style:{color:"var(--amber)"}},I={style:{color:"var(--cyan)"}},O={style:{color:"var(--lime)"}},V={__name:"Rules",setup(r){return(b,a)=>{const o=R("router-link");return f(),u("div",z,[e("div",y,[a[18]||(a[18]=l('<div class="panel" data-v-aae3789f><h1 class="hero-title" data-v-aae3789f>RÈGLES DU JEU</h1><p class="sub" style="margin-bottom:0;" data-v-aae3789f> Stratégie au tour par tour pour <b data-v-aae3789f>4 à 8 joueurs</b>. Chaque joueur dirige un <b data-v-aae3789f>dôme</b> alimenté par des <b class="lime" data-v-aae3789f>Batteries</b>. Chaque jour, tout le monde donne ses ordres en secret, puis le tour est résolu pour tous en même temps. </p></div><div class="panel" data-v-aae3789f><div class="ptitle" data-v-aae3789f>01 · But du jeu</div><ul data-v-aae3789f><li data-v-aae3789f>La partie dure <b data-v-aae3789f>15 jours</b> (15 tours) par défaut ; le créateur peut choisir de 5 à 30 tours.</li><li data-v-aae3789f>À la fin, le joueur qui possède le plus de <b class="teal" data-v-aae3789f>Razoonium</b> gagne.</li><li data-v-aae3789f>Un dôme éteint reste classé <b data-v-aae3789f>selon son Razoonium</b>, comme les autres : s&#39;éteindre arrête ta progression, pas ton score.</li><li data-v-aae3789f>Si un seul dôme reste allumé avant la fin, la partie s&#39;arrête ; le classement se fait alors au Razoonium.</li></ul><h3 data-v-aae3789f>Classement</h3><ol data-v-aae3789f><li data-v-aae3789f>Le plus de <b class="teal" data-v-aae3789f>Razoonium</b>, dômes éteints compris.</li><li data-v-aae3789f>Égalité : un dôme encore allumé passe devant un dôme éteint, puis le plus de Batteries.</li><li data-v-aae3789f>Entre dômes éteints : celui qui a tenu le plus longtemps passe devant.</li></ol></div>',2)),e("div",C,[a[2]||(a[2]=e("div",{class:"ptitle"},"02 · Ressources",-1)),e("h3",null,[s(n,{class:"mi",size:"1.1em",icon:i(c).battery},null,8,["icon"]),a[0]||(a[0]=d(" Batteries",-1))]),a[3]||(a[3]=l('<ul data-v-aae3789f><li data-v-aae3789f>Stock initial : <b class="lime" data-v-aae3789f>10 Batteries</b>.</li><li data-v-aae3789f>C&#39;est la ressource que tu dépenses pour agir. Elle peut être <b class="red" data-v-aae3789f>volée</b>.</li><li data-v-aae3789f>Coût de vie : ton dôme consomme <b data-v-aae3789f>1 Batterie</b> à chaque tour.</li><li data-v-aae3789f>Si tu finis un tour à <b class="red" data-v-aae3789f>0 Batterie ou moins</b>, ton dôme s&#39;éteint : tu ne joues plus, mais ton Razoonium reste compté au classement.</li></ul><div class="ex warn" data-v-aae3789f> Si tu engages toutes tes Batteries, le coût de vie te fait passer à −1. Seuls tes gains du tour (Génération, attaque restituée, pillage) peuvent alors te sauver. Garde une marge. </div>',2)),e("h3",null,[s(n,{class:"mi",size:"1.1em",icon:i(c).razoonium},null,8,["icon"]),a[1]||(a[1]=d(" Razoonium",-1))]),a[4]||(a[4]=l('<ul data-v-aae3789f><li data-v-aae3789f>C&#39;est <b data-v-aae3789f>ton score</b>.</li><li data-v-aae3789f>On l&#39;obtient en <b data-v-aae3789f>raffinant</b> des Batteries (<b data-v-aae3789f>3 Batteries → 1 Razoonium</b> ; le reliquat non raffinable t&#39;est rendu) ou en <b data-v-aae3789f>remportant un lot d&#39;Enchère</b>.</li><li data-v-aae3789f>Il est <b data-v-aae3789f>définitif</b> : il ne se dépense pas, ne se perd pas et <b data-v-aae3789f>ne peut pas être volé</b>.</li><li data-v-aae3789f>Une Batterie raffinée ne sert plus à agir, survivre ou se défendre. Tout l&#39;enjeu est de choisir <b data-v-aae3789f>quand</b> transformer ta puissance en score.</li></ul><div class="ex warn" data-v-aae3789f> Le raffinage se fait <b data-v-aae3789f>en fin de tour, après les attaques</b> : les Batteries misées en Raffinage <b class="red" data-v-aae3789f>peuvent être pillées</b> (en dernier, après ta Génération et ta réserve). Seul ce qui reste de la mise est raffiné (3 Batteries → 1 Razoonium). </div><h3 data-v-aae3789f>Réserve libre</h3><ul data-v-aae3789f><li data-v-aae3789f>Les Batteries que tu n&#39;engages dans aucune action forment ta <b data-v-aae3789f>réserve libre</b>.</li><li data-v-aae3789f>Elle paie le coût de vie et elle est <b class="red" data-v-aae3789f>pillée juste après ta Génération</b>.</li></ul>',4))]),e("div",T,[a[5]||(a[5]=l('<div class="ptitle" data-v-aae3789f>03 · Tour de jeu</div><ul data-v-aae3789f><li data-v-aae3789f>Chaque tour dure un temps fixé à la création de la partie (<b data-v-aae3789f>24h, 12h, 6h ou 1h</b>).</li><li data-v-aae3789f>Avant l&#39;échéance, répartis tes Batteries <b data-v-aae3789f>en secret</b> entre les 6 actions. Tu peux en combiner plusieurs dans le même tour, sans dépasser ce que tu possèdes.</li><li data-v-aae3789f>Tes ordres restent modifiables jusqu&#39;à la résolution.</li><li data-v-aae3789f>Avec la <b data-v-aae3789f>résolution anticipée</b>, le tour est résolu dès que tous les dômes allumés ont validé.</li><li data-v-aae3789f>Sans ordre validé, ton dôme ne fait rien : tout reste en réserve.</li><li data-v-aae3789f>Le <b data-v-aae3789f>journal de bord</b> ne te montre que ce qui te concerne, plus les événements publics (météo, lots révélés, dômes éteints, bilan des Batteries). Batteries et Razoonium de chacun sont publics ; boucliers et ordres des autres restent secrets.</li></ul>',2)),e("div",L,[(f(!0),u(m,null,g(i(B),t=>(f(),u("div",{key:t.key,class:"acard on",style:G({"--a":t.color})},[e("div",S,[e("div",E,[s(n,{icon:t.icon},null,8,["icon"])]),e("div",null,[e("div",N,p(t.name),1),e("div",h,p(t.tag),1)])]),e("div",k,p(t.desc),1)],4))),128))])]),a[19]||(a[19]=l('<div class="panel" data-v-aae3789f><div class="ptitle" data-v-aae3789f>04 · Générer</div><ul data-v-aae3789f><li data-v-aae3789f>La mise est consommée et remplacée en fin de tour par <b data-v-aae3789f>⌊mise × multiplicateur⌋</b> (arrondi à l&#39;inférieur).</li><li data-v-aae3789f>Multiplicateur : <b class="lime" data-v-aae3789f>×2</b> par temps Calme, <b class="red" data-v-aae3789f>×1,5</b> en <b data-v-aae3789f>Grisaille</b>, <b class="lime" data-v-aae3789f>×3</b> en <b data-v-aae3789f>Abondance</b>.</li><li data-v-aae3789f>Pas de plafond : tu mets ce que tu veux en Génération.</li><li data-v-aae3789f>Mais la mise en Génération est <b class="red" data-v-aae3789f>la première pillée</b> : le rendement est calculé sur ce qu&#39;il en reste après les attaques. Plus tu génères, plus tu es une cible.</li></ul><div class="ex" data-v-aae3789f><b data-v-aae3789f>Exemple</b> : tu mets 10 en Génération. Sans attaque, tu récupères 10 × 2 = <b data-v-aae3789f>20</b> (+10). Si on te pille 4 Batteries dans ta Génération, tu ne récupères que 6 × 2 = <b data-v-aae3789f>12</b>. </div></div><div class="panel" data-v-aae3789f><div class="ptitle" data-v-aae3789f>05 · Défendre</div><ul data-v-aae3789f><li data-v-aae3789f>Chaque Batterie en Défense te donne <b data-v-aae3789f>1 dé de défense</b> pour ce tour.</li><li data-v-aae3789f>Le Bouclier ne dure que <b data-v-aae3789f>le tour où il est posé</b>.</li><li data-v-aae3789f>Chaque dé de défense perdant donne sa Batterie à l&#39;attaquant ; chaque dé gagnant te rapporte la Batterie de l&#39;attaquant.</li><li data-v-aae3789f>Les Batteries de Bouclier sont <b class="red" data-v-aae3789f>consommées</b> en fin de tour, qu&#39;elles aient servi ou non.</li><li data-v-aae3789f>Les Boucliers ne sont pas pillables.</li></ul><div class="ex warn" data-v-aae3789f><b data-v-aae3789f>Le dilemme</b> : une Batterie en Défense ne génère rien et disparaît. Tu génères à fond en restant exposé, ou tu génères moins pour te protéger ? </div></div><div class="panel" data-v-aae3789f><div class="ptitle" data-v-aae3789f>06 · Attaquer &amp; piller</div><p data-v-aae3789f>Tu ne peux attaquer qu&#39;<b data-v-aae3789f>un seul joueur par tour</b>. Chaque Batterie d&#39;attaque te donne <b data-v-aae3789f>1 dé</b> (dés à 6 faces).</p><ol style="margin-top:8px;" data-v-aae3789f><li data-v-aae3789f>Attaquant et défenseur lancent leurs dés et les <b data-v-aae3789f>trient du plus fort au plus faible</b>.</li><li data-v-aae3789f>On compare les dés <b data-v-aae3789f>un à un, dans l&#39;ordre</b> (le meilleur contre le meilleur…), autant de fois que le camp qui a le moins de dés.</li><li data-v-aae3789f>Dé d&#39;attaque <b data-v-aae3789f>strictement plus fort</b> : l&#39;attaquant garde sa Batterie et <b class="lime" data-v-aae3789f>prend la Batterie de Bouclier</b>.</li><li data-v-aae3789f>Sinon (<b data-v-aae3789f>égalité comprise</b>) : le défenseur <b class="red" data-v-aae3789f>prend la Batterie d&#39;attaque</b>.</li><li data-v-aae3789f>Chaque dé d&#39;attaque <b data-v-aae3789f>en trop</b> te rend sa Batterie et <b data-v-aae3789f>pille 2 Batteries</b> à la cible : d&#39;abord dans sa <b data-v-aae3789f>Génération</b>, puis dans sa <b data-v-aae3789f>réserve libre</b> (y compris transferts reçus ce tour), puis dans son <b data-v-aae3789f>Raffinage</b>.</li><li data-v-aae3789f>On ne pille que ce qui existe : Boucliers, Razoonium déjà acquis, mises d&#39;enchère, attaques et transferts envoyés sont hors d&#39;atteinte.</li></ol><p style="margin-top:10px;" data-v-aae3789f><b data-v-aae3789f>Plusieurs attaquants</b> sur la même cible : tous leurs dés d&#39;attaque sont triés ensemble face aux dés de défense. À dé égal, passe d&#39;abord celui qui a lancé le plus de dés, puis celui qui a le moins de Batteries. Les dés en trop sont les plus faibles du lot. </p><div class="ex" data-v-aae3789f><b data-v-aae3789f>Exemple</b> : tu attaques Nat avec <b data-v-aae3789f>4</b>, Nat défend avec <b data-v-aae3789f>2</b>, a 3 en Génération et une réserve libre de 3. <ul data-v-aae3789f><li data-v-aae3789f>Tes dés : 6 · 4 · 3 · 1. Ceux de Nat : 5 · 4.</li><li data-v-aae3789f>6 contre 5 : tu gagnes et prends 1 Batterie de Bouclier.</li><li data-v-aae3789f>4 contre 4 : égalité, Nat prend 1 de tes Batteries.</li><li data-v-aae3789f>Tes 2 dés en trop (3 et 1) te reviennent et pillent 4 Batteries : les 3 de la Génération de Nat, puis 1 dans sa réserve.</li><li data-v-aae3789f>Tu finis à <b class="lime" data-v-aae3789f>+8</b> pour 4 engagées (3 récupérées + 1 Bouclier + 4 pillées). Nat gagne 1 Batterie, perd ses 2 Batteries de Bouclier et ne génère rien.</li></ul></div></div><div class="panel" data-v-aae3789f><div class="ptitle" data-v-aae3789f>07 · Transférer</div><ul data-v-aae3789f><li data-v-aae3789f>Tu envoies X Batteries à <b data-v-aae3789f>un seul joueur</b> par tour.</li><li data-v-aae3789f>Il les reçoit <b data-v-aae3789f>pendant le tour, avant les attaques</b>, dans sa réserve libre : elles <b class="red" data-v-aae3789f>peuvent être pillées</b> ce tour-ci.</li></ul></div><div class="panel" data-v-aae3789f><div class="ptitle" data-v-aae3789f>08 · Enchère quotidienne</div><ul data-v-aae3789f><li data-v-aae3789f><b data-v-aae3789f>⌊joueurs encore en jeu / 2⌋</b> lots de <b class="teal" data-v-aae3789f>Razoonium</b> (0 à 4 chacun). Leur contenu reste <b data-v-aae3789f>caché jusqu&#39;à la résolution</b> ; ils sont triés du plus gros au plus petit.</li><li data-v-aae3789f><b class="red" data-v-aae3789f>Tout le monde paie sa mise</b>, gagnant ou perdant.</li><li data-v-aae3789f>Les joueurs sont classés par <b data-v-aae3789f>mise décroissante</b> : le 1ᵉʳ remporte le 1ᵉʳ lot, le 2ᵉ le 2ᵉ lot, etc. Le Razoonium s&#39;ajoute <b data-v-aae3789f>directement au score</b> (imprenable).</li><li data-v-aae3789f>Égalité de mise : le joueur qui avait le moins de Batteries en début de tour passe devant.</li></ul><div class="ex warn" data-v-aae3789f><b data-v-aae3789f>Quitte ou double</b> : 1 Razoonium vaut 3 Batteries au raffinage. Miser 4 pour un lot de 4, c&#39;est l&#39;équivalent de 12 Batteries ; pour un lot de 0, ou si on te passe devant, tu perds tout. </div><div class="ex" data-v-aae3789f><b data-v-aae3789f>Exemple</b> : 2 lots, révélés à la résolution : 3 et 0. Tristan mise 4, Nat 2, Basto 2 (Nat a moins de Batteries que Basto). Tristan paie 4 et gagne <b class="teal" data-v-aae3789f>3 Razoonium</b>. Nat paie 2 et ne gagne rien (lot vide). Basto paie 2 et ne gagne rien. </div></div>',5)),e("div",A,[a[15]||(a[15]=e("div",{class:"ptitle"},"09 · Météo (D6)",-1)),a[16]||(a[16]=e("p",{style:{"margin-bottom":"12px"}},"Lancée à chaque résolution : personne ne la connaît au moment de donner ses ordres.",-1)),e("div",w,[e("div",null,[a[7]||(a[7]=e("span",{class:"d"},"1",-1)),e("b",D,[s(n,{class:"mi",size:"1.1em",icon:i(v).gloom.icon},null,8,["icon"]),a[6]||(a[6]=d(" Grisaille",-1))]),a[8]||(a[8]=e("span",null,"Génération ×1,5",-1))]),e("div",null,[a[10]||(a[10]=e("span",{class:"d"},"2-5",-1)),e("b",I,[s(n,{class:"mi",size:"1.1em",icon:i(v).calm.icon},null,8,["icon"]),a[9]||(a[9]=d(" Calme",-1))]),a[11]||(a[11]=e("span",null,"Génération ×2",-1))]),e("div",null,[a[13]||(a[13]=e("span",{class:"d"},"6",-1)),e("b",O,[s(n,{class:"mi",size:"1.1em",icon:i(v).abundance.icon},null,8,["icon"]),a[12]||(a[12]=d(" Abondance",-1))]),a[14]||(a[14]=e("span",null,"Génération ×3",-1))])])]),a[20]||(a[20]=l('<div class="panel" data-v-aae3789f><div class="ptitle" data-v-aae3789f>10 · Ordre de résolution</div><ol data-v-aae3789f><li data-v-aae3789f><b data-v-aae3789f>Coût de vie</b> : −1 Batterie par dôme.</li><li data-v-aae3789f><b data-v-aae3789f>Météo</b> : lancer du dé, qui fixe le multiplicateur de Génération.</li><li data-v-aae3789f><b data-v-aae3789f>Enchères</b> : toutes les mises sont payées, les lots sont révélés et attribués.</li><li data-v-aae3789f><b data-v-aae3789f>Transferts</b> : arrivée dans la réserve du destinataire.</li><li data-v-aae3789f><b data-v-aae3789f>Attaques</b> : lancers de dés et duels, puis pillage par les dés en trop, 2 Batteries chacun (Génération, puis réserve, puis Raffinage).</li><li data-v-aae3789f><b data-v-aae3789f>Boucliers</b> : les Batteries de Bouclier restantes sont consommées.</li><li data-v-aae3789f><b data-v-aae3789f>Raffinage &amp; Génération</b> sur les mises restantes, plus les Batteries gagnées et le butin.</li><li data-v-aae3789f><b data-v-aae3789f>Bilan</b> : tout dôme à 0 Batterie ou moins s&#39;éteint.</li></ol></div>',1)),s(o,{to:i(x).token?"/":"/login",class:"btn primary block"},{default:q(()=>[...a[17]||(a[17]=[d("Entrer dans l'arène ▸",-1)])]),_:1},8,["to"])])])}}},M=j(V,[["__scopeId","data-v-aae3789f"]]);export{M as default};
